//Reference shader structure from Neon Orbs
//https://openprocessing.org/sketch/820299

let theShader;
let sourceGraphics,shaderGraphics;
var boolTrigger;

function preload(){
	theShader = getShader(this._renderer);
}

function setup() {
	createCanvas(4/3*windowHeight, windowHeight);
	sourceGraphics= createGraphics(width,height)
	shaderGraphics = createGraphics(width,height,WEBGL)
	sourceGraphics.background(0) 
}

function draw() {
	background(0, 200)
	sourceGraphics.background(0, 255)

	shaderGraphics.shader(theShader)
	theShader.setUniform('u_resolution',[1,1])
	theShader.setUniform('u_time', millis()*0.0005)
	theShader.setUniform('u_tex', sourceGraphics)
	theShader.setUniform('u_mouseX', -(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))
	theShader.setUniform('u_mouseY', (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))

	shaderGraphics.rect(-width/2,-height/2,width,height)
	blendMode(ADD)
	image(sourceGraphics,0,0)
	image(shaderGraphics,0,0)
	blendMode(BLEND)
	}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}


// === Tab: shader ===
function getShader(_renderer) {
	const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;

		void main() {
			vTexCoord = aTexCoord;
			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
			gl_Position = positionVec4;
		}
	`;

	// noprotect
	const frag = `
		precision highp float;

		varying vec2 vTexCoord;
		uniform vec2 u_resolution;
		const float WIDTH = ${windowWidth}.0;
		const float HEIGHT = ${windowHeight}.0;
		uniform float u_time;
		uniform float u_mouseX;
		uniform float u_mouseY;

		vec3 permute(vec3 x) { return mod(((x*34.0)+1.0)*x, 289.0); }

		float snoise(vec2 v){
			const vec4 C = vec4(0.211324865405187, 0.366025403784439,
							 -0.577350269189626, 0.024390243902439);
			vec2 i  = floor(v + dot(v, C.yy) );
			vec2 x0 = v -   i + dot(i, C.xx);
			vec2 i1;
			i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
			vec4 x12 = x0.xyxy + C.xxzz;
			x12.xy -= i1;
			i = mod(i, 289.0);
			vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 ))
			+ i.x + vec3(0.0, i1.x, 1.0 ));
			vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy),
				dot(x12.zw,x12.zw)), 0.0);
			m = m*m ;
			m = m*m ;
			vec3 x = 2.0 * fract(p * C.www) - 1.0;
			vec3 h = abs(x) - 0.5;
			vec3 ox = floor(x + 0.5);
			vec3 a0 = x - ox;
			m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
			vec3 g;
			g.x  = a0.x  * x0.x  + h.x  * x0.y;
			g.yz = a0.yz * x12.xz + h.yz * x12.yw;
			return 130.0 * dot(m, g);
		}

		float random (vec2 st) {
				return fract(sin(dot(st.xy,
														 vec2(12.9898,78.233)))*
						43758.5453123);
		}

		float random1d (vec2 st) {
				return fract(sin(dot(st.xy,
														 vec2(12.9898,78.233)))*
						43758.5453123);
		}

		float circle(vec2 uv, vec2 pos, float _rad, float _blur){
				float rad = _rad;
				float blurLevel = rad - _blur;
				float dist = length(uv + pos);
				return smoothstep(rad, blurLevel, dist);
		}


		void main() {
			vec2 coord = vTexCoord.xy / u_resolution.xy;		
			float x = vTexCoord.x * WIDTH;
			float y = vTexCoord.y * HEIGHT;
			float v = 0.0;
			float color = 0.0;
			color += 1.0 - (pow(coord.y, 0.1)) * 1.2;
			color += snoise(vec2(coord.x + snoise(coord * 4.0 - u_time) * 0.1 + u_time * 0.5, coord.y * 20.0)) * 0.03;
			color += random(coord) * random(coord * 100.0) * 0.5;
			color -= abs(snoise(coord * 100.0 - u_time * 1.1 + snoise(coord * 100.0+ u_time * 2.1 + u_mouseX*0.001) * 0.5) * 0.1);
			color += 0.2 - snoise(coord * 1.0 - u_time * 0.01 + snoise(coord * 3.0 - u_time * 0.1 + vec2(u_mouseX*0.001, u_mouseY*0.001) + snoise(coord * 10.0 + u_time * 0.2 + snoise(coord * 50.0+ u_time * 0.1) * 0.05 + snoise(coord * 30.0 - u_time * 0.1 + snoise(coord * 50.0) * 0.5) * 0.1) * 0.15) * 0.1) * 0.9;
			vec3 col = vec3(color, color, color);
			col.x+=(snoise(vec2(coord.x, coord.y * 0.1- u_time * 0.1 + u_mouseX*0.001))) * 0.35;
			col.z+=abs(snoise(vec2(coord.x, coord.y * 2.0- u_time * 0.1) + snoise(coord * 2.0 + u_mouseX*0.001) * 0.1)) * 0.75;
			gl_FragColor = vec4(col, 1.0);
		}
	`;

	return createShader(vert, frag);
}

